#include <bits/stdc++.h>
using namespace std;

void apply(vector<int>& p, int x, int y) {
    int n = p.size();
    // [Suffix y | Middle | Prefix x]
    vector<int> np;
    for (int i = n - y; i < n; i++) np.push_back(p[i]);
    for (int i = x; i < n - y; i++) np.push_back(p[i]);
    for (int i = 0; i < x; i++) np.push_back(p[i]);
    p = np;
}

int main(){
    int n;
    scanf("%d", &n);
    vector<int> p(n);
    for (int i = 0; i < n; i++) scanf("%d", &p[i]);

    vector<pair<int,int>> ops;

    // Place elements 1, 2, ..., n into positions 0, 1, ..., n-1
    for (int target = 0; target < n - 2; target++) {
        // Find where value (target+1) currently is
        int pos = -1;
        for (int i = target; i < n; i++) {
            if (p[i] == target + 1) { pos = i; break; }
        }
        if (pos == target) continue; // already in place

        // Step 1: Move element from pos to position n-1 (last position)
        if (pos != n - 1) {
            // We want p[pos] to end up at position n-1
            // After apply(x, y): prefix of length x goes to end
            // So if we set x = pos + 1, the element at p[pos] (last of prefix) goes to position n-1
            // We need x + y < n, x > 0, y > 0
            // x = pos + 1, y = 1, need pos + 1 + 1 < n => pos < n - 2
            // If pos == n - 2, use x = pos + 1 = n - 1, y = 1, x + y = n, not < n!
            // Instead use x = pos + 1, y = 1 when pos < n - 2
            // When pos == n - 2: x = n-1, y must be >= 1, x+y < n impossible. 
            //   Use x = 1, y = 1: moves p[n-1] to front, p[0] to end. Then pos might change.
            //   Or: x = pos, y = 1 => element at pos is now in middle at index pos-1+1=pos (after suffix of 1). Hmm.
            //   Actually just swap to bring it: x = n-2, y = 1 => suffix=[p[n-1]], prefix=[p[0]..p[n-3]], middle=[p[n-2]]
            //   Result: [p[n-1], p[n-2], p[0]..p[n-3]]. Element was at n-2, now at position 1. Not helpful directly.
            // Let me just use: x = pos+1, y >= 1, x+y < n
            int x = pos + 1, y = 1;
            if (x + y >= n) { y = 1; x = pos; } // x=pos, y=1, pos+1<n since pos<=n-2 and n>=3
            if (x > 0 && y > 0 && x + y < n) {
                ops.push_back({x, y});
                apply(p, x, y);
            }
            // Re-find
            pos = -1;
            for (int i = 0; i < n; i++) if (p[i] == target + 1) { pos = i; break; }
            if (pos == target) continue;
        }

        // Step 2: Move element from pos to position target
        // Set y = n - pos so suffix includes element. After op, suffix goes to front.
        // Element at pos is at index 0 of suffix, so goes to position 0 in result.
        // We want it at position target. So set x = target, y = n - pos.
        // Need x > 0 (target >= 1 if target > 0), y > 0, x + y < n
        if (pos == target) continue;
        int x2 = target, y2 = n - pos;
        if (x2 == 0) { x2 = 1; } // adjust; element will be at position 1 instead... handle separately
        if (x2 > 0 && y2 > 0 && x2 + y2 < n) {
            ops.push_back({x2, y2});
            apply(p, x2, y2);
        } else if (target == 0 && pos > 0 && pos < n - 1) {
            // x=1, y=n-pos, need 1+n-pos<n => pos>1
            // If pos==1: x=1,y=n-1,sum=n not<n. Use x=1,y=n-2
            int yy = n - pos;
            if (1 + yy >= n) yy = n - 2;
            ops.push_back({1, yy});
            apply(p, 1, yy);
        }
    }

    printf("%d\n", (int)ops.size());
    for (auto& [x, y] : ops) printf("%d %d\n", x, y);
}
